/**
 * Link version 3, frozen: the scenario shapes the channels carry.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 3 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV3.test.ts` checks the living types against it.
 *
 * What version 3 adds to the closed unions of version 2: selectors (slowest, id, pinned, pendingBoostTarget, newest, oldest,
 * matching), typed expressions and the conditions over them (compare, present, absent, contains*, entriesWhere, entryCount),
 * the actions of the whole lifecycle (join, claims, earnTurbo, runAutomation, setSetting, clearSetting, useProfile, setPin,
 * clearPin, pauseScenario, startAutovote, stopAutovote, handoffScenario), rule stages, phase bindings, schedules, profile,
 * pins and photo pool, the installation scope, and the lifecycle fields of a scenario's state.
 */

export type ScenarioIssueV3 = { path: string; message: string };

type ComparisonOpV3 = '<' | '<=' | '=' | '!=' | '>=' | '>';
type DurationV3 = number | string;
type EntryFieldV3 = 'votes' | 'rank' | 'votesPerHour' | 'speedRatio' | 'boosted' | 'turbo' | 'boosting';

type EntryPredicateV3 = { field: EntryFieldV3; op: ComparisonOpV3; value: number | boolean };

type ScenarioSelectorV3 =
    | { by: 'slot'; index: number }
    | { by: 'memory'; slot: string }
    | { by: 'fastest' | 'slowest'; window?: DurationV3; skipProtected?: boolean }
    | { by: 'mostVotes' | 'fewestVotes' | 'bestRank' | 'worstRank' | 'boosted' | 'turbo'; skipProtected?: boolean }
    | { by: 'id'; id: string }
    | { by: 'pinned'; power: 'boost' | 'turbo' }
    | { by: 'pendingBoostTarget' }
    | { by: 'newest' | 'oldest'; time: 'exact' | 'observed' }
    | {
          by: 'matching';
          where: EntryPredicateV3[];
          order: 'votes' | 'rank' | 'age';
          direction: 'asc' | 'desc';
      };

type ScenarioExprV3 =
    | {
          kind: 'literal';
          value: number;
          quantity:
              | 'instant'
              | 'duration'
              | 'percent'
              | 'ratio'
              | 'count'
              | 'votes'
              | 'votesPerHour'
              | 'keys'
              | 'swaps'
              | 'fills'
              | 'coins';
          unit?: 'seconds' | 'minutes' | 'hours' | 'days';
      }
    | { kind: 'literal'; value: boolean }
    | { kind: 'literal'; value: string }
    | { kind: 'literal'; value: string[] }
    | {
          kind: 'fact';
          name:
              | 'clock.now'
              | 'phase.enteredAt'
              | 'phase.elapsed'
              | 'challenge.id'
              | 'challenge.title'
              | 'challenge.type'
              | 'challenge.tags'
              | 'challenge.start'
              | 'challenge.end'
              | 'challenge.timeLeft'
              | 'challenge.elapsed'
              | 'challenge.elapsedPercent'
              | 'challenge.entries'
              | 'challenge.freeSlots'
              | 'challenge.exposure'
              | 'challenge.rank'
              | 'challenge.votes'
              | 'challenge.players'
              | 'challenge.maxPlayers'
              | 'challenge.maxPhotoSubmits'
              | 'challenge.joinPrice'
              | 'challenge.membership'
              | 'boost.state'
              | 'boost.freeExpiry'
              | 'boost.freeRemaining'
              | 'boost.open'
              | 'boost.keyUnlocked'
              | 'turbo.state'
              | 'turbo.mode'
              | 'turbo.opensAt'
              | 'balance.keys'
              | 'balance.swaps'
              | 'balance.fills'
              | 'balance.coins'
              | 'missions.joinNeed'
              | 'missions.fillNeed'
              | 'missions.turboNeed'
              | 'missions.boostNeed'
              | 'missions.voteNeed'
              | 'missions.nextExpiry'
              | 'rewards.claimable'
              | 'rewards.claimableCount'
              | 'remote.enabled'
              | 'remote.connected'
              | 'photos.eligibleCount'
              | 'photos.eligibleAtLeast'
              | 'photos.hasEligible'
              | 'entry.votes'
              | 'entry.rank'
              | 'entry.votesPerHour'
              | 'entry.speedRatio'
              | 'entry.boosted'
              | 'entry.turbo'
              | 'entry.boosting'
              | 'entry.age'
              | 'entry.minAge'
              | 'entry.ageExact'
              | 'entry.uncertainSubmission'
              | 'entry.pinned';
          select?: ScenarioSelectorV3;
          window?: DurationV3;
      }
    | { kind: 'setting'; key: string; view: 'base' | 'effective' }
    | { kind: 'offset'; from: ScenarioExprV3; by: ScenarioExprV3; direction: 'before' | 'after' }
    | { kind: 'difference'; from: ScenarioExprV3; to: ScenarioExprV3 }
    | { kind: 'add' | 'subtract'; left: ScenarioExprV3; right: ScenarioExprV3 }
    | { kind: 'earlier' | 'later' | 'min' | 'max'; of: ScenarioExprV3[] };

type ScenarioConditionV3 =
    | { type: 'dailyWindow'; from: string; to: string }
    | { type: 'beforeEnd' | 'afterStart' | 'inPhaseFor'; min?: DurationV3; max?: DurationV3 }
    | { type: 'elapsedPercent'; min?: number; max?: number }
    | {
          type: 'entries' | 'freeSlots' | 'exposure' | 'challengeRank' | 'challengeVotes';
          op: ComparisonOpV3;
          value: number;
      }
    | { type: 'boostState' | 'turboState'; in: string[] }
    | { type: 'balance'; currency: 'keys' | 'swaps' | 'fills' | 'coins'; op: ComparisonOpV3; value: number }
    | { type: 'memorySet'; slot: string }
    | {
          type: 'entry';
          select: ScenarioSelectorV3;
          field: EntryFieldV3;
          op: ComparisonOpV3;
          value: number | boolean;
          window?: DurationV3;
      }
    | { type: 'compare'; left: ScenarioExprV3; op: ComparisonOpV3; right: ScenarioExprV3 }
    | { type: 'present' | 'absent'; value: ScenarioExprV3 }
    | { type: 'contains' | 'containsAny' | 'containsAll'; list: ScenarioExprV3; value: ScenarioExprV3 }
    | { type: 'entriesWhere'; quantifier: 'any' | 'all'; where: EntryPredicateV3[] }
    | { type: 'entryCount'; where: EntryPredicateV3[]; op: ComparisonOpV3; value: number }
    | { type: 'all' | 'any'; of: ScenarioConditionV3[] }
    | { type: 'not'; condition: ScenarioConditionV3 };

type PhotoSourceV3 = 'best' | { memory: string };

type ScenarioActionV3 =
    | { type: 'enterPhoto'; photo: PhotoSourceV3; remember?: string }
    | {
          type: 'swap';
          entry: ScenarioSelectorV3;
          with: PhotoSourceV3;
          rememberRemoved?: string;
          rememberAdded?: string;
      }
    | { type: 'boost' | 'turbo'; entry: ScenarioSelectorV3 }
    | { type: 'unlockBoost' | 'fillExposure' | 'claimChallengeReward' | 'earnTurbo' | 'startAutovote' | 'stopAutovote' }
    | { type: 'vote'; toExposure: number }
    | { type: 'remember'; slot: string; entry: ScenarioSelectorV3 }
    | { type: 'forget'; slot: string }
    | { type: 'goto'; phase: string }
    | { type: 'notify'; message: string }
    | { type: 'join'; maxCoins?: ScenarioExprV3 }
    | { type: 'claimMissionReward'; missionId: string }
    | {
          type: 'runAutomation';
          operation: 'submit' | 'boost' | 'turbo' | 'unlockBoost' | 'swap' | 'fillExposure' | 'vote' | 'join';
      }
    | { type: 'setSetting'; key: string; value: ScenarioExprV3 | boolean | number | string | string[] }
    | { type: 'clearSetting'; key: string }
    | { type: 'useProfile'; name: string | null }
    | { type: 'setPin'; power: 'boost' | 'turbo'; entry: ScenarioSelectorV3 }
    | { type: 'clearPin'; power: 'boost' | 'turbo' }
    | { type: 'pauseScenario'; reason?: string }
    | { type: 'handoffScenario'; to: string | null };

type ScenarioRuleV3 = {
    id: string;
    label?: string;
    repeat?: 'always' | 'once' | 'oncePerPhase' | 'oncePerDay';
    stages?: ('account' | 'preJoin' | 'active' | 'postClose')[];
    if?: ScenarioConditionV3[];
    do: ScenarioActionV3[];
};

type ScenarioWindowScheduleV3 = { rows: { at: ScenarioExprV3; duration: ScenarioExprV3 }[] };

type ScenarioPhaseV3 = {
    settings?: { [key: string]: unknown };
    bindings?: { [key: string]: ScenarioExprV3 };
    schedules?: {
        submit?: { alignment: 'end' | 'absolute'; rows: { count: number; at: ScenarioExprV3 }[] };
        vote?: ScenarioWindowScheduleV3;
        pause?: ScenarioWindowScheduleV3;
    };
    profile?: string;
    pins?: { boost?: string | null; turbo?: string | null };
    photoPool?: { name: string; only?: boolean; inOrder?: boolean };
    rules?: ScenarioRuleV3[];
};

export type ScenarioDocumentV3 = {
    name: string;
    version: 1;
    description?: string;
    scope?: 'challenge' | 'installation';
    start: string;
    limits?: { swaps?: number; keys?: number; fills?: number; coins?: number };
    phases: { [key: string]: ScenarioPhaseV3 };
};

type SpendActionV3 = 'swap' | 'unlockBoost' | 'fillExposure';

type ScenarioFiredRecordV3 = {
    at: number;
    day?: number;
    phaseEnteredAt?: number;
    unclearHalt?: SpendActionV3;
    haltOrigin?: 'pending';
};

type RowStateV3<Known extends object> =
    | ({ state: 'known' } & Known)
    | { state: 'absent'; reason: string }
    | { state: 'unknown'; reason: string };

type ResolvedWindowScheduleV3 = { rows: RowStateV3<{ start: number; end: number }>[] };

type ScenarioPublicationV3 = {
    revision: number;
    documentFingerprint: string;
    phase: string;
    phaseEnteredAt: number;
    observedAt: number;
    validUntil: number | null;
    bindings: { [key: string]: unknown };
    profile: string | null;
    schedules?: {
        submit?: { alignment: 'end' | 'absolute'; rows: ({ count: number } & RowStateV3<{ at: number }>)[] };
        vote?: ResolvedWindowScheduleV3;
        pause?: ResolvedWindowScheduleV3;
    };
    generation?: number;
};

type ScenarioEpochV3 = { all: number; gen: number };

export type ScenarioStateV3 = {
    scenario: string;
    phase: string;
    phaseEnteredAt: number;
    memory: { [key: string]: string };
    fired: { [key: string]: ScenarioFiredRecordV3 };
    inFlight: null | {
        ruleId: string;
        actionIndex: number;
        unclear?: SpendActionV3[];
        unclearAt?: number;
        pending?: SpendActionV3;
        lost?: SpendActionV3[];
    };
    spent: { [key: string]: number };
    history?: { [key: string]: [number, number][] };
    outbox?: { id: string; at: number; message: string }[];
    lastAction?: null | { at: number; ruleId: string; action: string; outcome: string };
    lastError?: null | { at: number; message: string };
    updatedAt?: number;
    gen?: number;
    published?: ScenarioPublicationV3;
    generation?: number;
    paused?: null | { at: number; reason: string };
    withdrawn?: null | { at: number; epoch: number };
    handoff?: null | { from: string; to: null | string; generation: number; at: number };
    phasePatch?: { [key: string]: unknown };
    phaseProfile?: null | string;
    phasePins?: { boost?: null | string; turbo?: null | string };
    poolProgress?: { [key: string]: { consumed: string[]; reserved: string[] } };
    lastRequest?: null | { id: string; result: string; at: number };
    publicationUnreadable?: true;
    epoch?: ScenarioEpochV3;
};

/** Where a phase's settings come from, and whether they can be read now. */
export type ScenarioOverlayStatusV3 = {
    bound: boolean;
    available: boolean;
    reason: null | string;
    sources: { patch: string[]; literals: string[]; bindings: string[]; profile: string[] };
    published: null | { revision: number; observedAt: number; validUntil: null | number; profile: null | string };
};

type SimulationOutcomeV3 = 'success' | 'refused' | 'unclear';
export type SimulationOperationV3 = 'submit' | 'join' | 'claim' | 'boost' | 'turbo' | 'swap' | 'fill' | 'keyUnlock';

export type SimulationSubjectV3 =
    | { kind: 'installation' }
    | { kind: 'candidate' | 'active' | 'completed'; challengeId: string };

export type SimulationAssumptionsV3 = {
    outcomes?: {
        submit?: SimulationOutcomeV3;
        join?: SimulationOutcomeV3;
        claim?: SimulationOutcomeV3;
        boost?: SimulationOutcomeV3;
        turbo?: SimulationOutcomeV3;
        swap?: SimulationOutcomeV3;
        fill?: SimulationOutcomeV3;
        keyUnlock?: SimulationOutcomeV3;
    };
    snapshots?: { at: number; facts: { challenge?: unknown; bankroll?: unknown; library?: unknown[] } }[];
};

export type SimulationRequestV3 = {
    scenario: { name: string } | { draft: ScenarioDocumentV3 };
    subject: SimulationSubjectV3;
    until: number;
    assumptions?: SimulationAssumptionsV3;
};

export type SimulationEventV3 =
    | { type: 'operation'; at: number; subject: string; operation: string; outcome: SimulationOutcomeV3; applied: true }
    | { type: 'rule'; at: number; subject: string; phase: string; ruleId: string; applied: true }
    | { type: 'phase'; at: number; subject: string; from: string; to: string; applied: true }
    | { type: 'published'; at: number; subject: string; phase: string; validUntil: number | null; applied: true }
    | { type: 'notice'; at: number; subject: string; message: string; applied: true }
    | { type: 'preview'; at: number; subject: string; reason: 'next-wake'; applied: false };

export type SimulationDeadlineV3 =
    | { kind: 'submit'; count: number; at: number | null }
    | { kind: 'vote' | 'pause'; start: number | null; end: number | null }
    | { kind: 'publication'; validUntil: number | null };
